[Form]
public class AVAChangeBOMRoute extends FormRun
{
    InventDimCtrl_Frm   inventDimFormSetupBOMVersion, inventDimFormSetupRouteVersion;
    ProdTable           callerProdTable;
    QueryBuildRange     rangeBomItem, rangeBomApproved, rangeBomDateFrom, rangeBomDateTo,
                        rangeRouteItem, rangeRouteApproved, rangeRouteDateFrom, rangeRouteDateTo;

    BomId               actualBomId;
    RouteId             actualRouteId;



}

public void init()
{
    super();

    this.updateDesignBOMVersion(InventDimFormDesignUpdate::Init);
    this.updateDesignRouteVersion(InventDimFormDesignUpdate::Init);

    if (!this.args().record()==tablenum(ProdTable))
    {
        throw error("@SYS113480");
    }

    callerProdTable = this.args().record();
    this.CallerProdTableChanged();
}

public void updateDesignRouteVersion(InventDimFormDesignUpdate _mode)
{
    InventDimParm   inventDimParm;
    InventTable     inventTable = InventTable::find(RouteVersion.ItemId);
    Set             validDataSources;

    switch (_mode)
    {
        case InventDimFormDesignUpdate::Init        :
            if (!inventDimFormSetupRouteVersion)
            {
                validDataSources = new Set(Types::String);
                validDataSources.add(routeVersion_ds.name());
                validDataSources.add(inventDimRouteVersion_ds.name());
                inventDimFormSetupRouteVersion = InventDimCtrl::newFromFormValidDataSources(element,validDataSources);
            }
            inventDimParm.initDimBOMRouteVersion(InventDimGroupSetup::newInventTable(inventTable));
            inventDimFormSetupRouteVersion.parmDimParmVisibleGrid(inventDimParm);
            inventDimFormSetupRouteVersion.parmDimParmEnabled(inventDimParm);
            inventDimFormSetupRouteVersion.formSetControls(true);
            break;

        case InventDimFormDesignUpdate::Active      :
        case InventDimFormDesignUpdate::LinkActive  :
        case InventDimFormDesignUpdate::FieldChange :
            inventDimParm.initDimBOMRouteVersion(InventDimGroupSetup::newInventTable(inventTable));
            inventDimFormSetupRouteVersion.parmDimParmVisibleGrid(inventDimParm);
            inventDimFormSetupRouteVersion.parmDimParmEnabled(inventDimParm);
            inventDimFormSetupRouteVersion.formSetControls(true);
            break;

        default:
            throw error(strfmt("@SYS54195",funcname()));
    }
}

public void updateDesignBOMVersion(InventDimFormDesignUpdate _mode)
{
    InventDimParm   inventDimParmVisible;
    InventDimParm   inventDimParmEnabled;
    Set             validDataSources;
    InventTable     inventTable             = bomVersion.inventTable();

    switch (_mode)
    {
        case InventDimFormDesignUpdate::Init        :
            if (!inventDimFormSetupBOMVersion)
            {
                validDataSources = new Set(Types::String);
                validDataSources.add(bomVersion_ds.name());
                validDataSources.add(inventDimBOMVersion_ds.name());
                inventDimFormSetupBOMVersion = InventDimCtrl::newFromFormValidDataSources(element,validDataSources);
            }
            inventDimParmVisible.initDimBOMRouteVersion(InventDimGroupSetup::newInventTable(inventTable));
            inventDimFormSetupBOMVersion.parmDimParmVisibleGrid(inventDimParmVisible);
            inventDimParmEnabled.initDimBOMVersionEnable(InventDimGroupSetup::newInventTable(inventTable), bomVersion);
            inventDimFormSetupBOMVersion.parmDimParmEnabled(inventDimParmEnabled);
            inventDimFormSetupBOMVersion.formSetControls(true);
            break;

        case InventDimFormDesignUpdate::Active      :
        case InventDimFormDesignUpdate::FieldChange :
            inventDimParmEnabled.initDimBOMVersionEnable(InventDimGroupSetup::newInventTable(inventTable), bomVersion);
            inventDimFormSetupBOMVersion.parmDimParmEnabled(inventDimParmEnabled);
            inventDimFormSetupBOMVersion.formSetControls(true);
            break;

        default: 
            throw error(strfmt("@SYS54195",funcname()));
    }
}

public void callerProdTableChanged()
{
    actualRouteId=callerProdTable.RouteId;
    actualBomId=callerProdTable.BOMId;

    this.replaceButtonEnabled();
}

public void replaceButtonEnabled()
{
    boolean enabled = (callerProdTable.ProdStatus == ProdStatus::Created
                        && bomVersion
                        && RouteVersion);

    ReplaceButton.enabled(enabled);
}

public void selectActual()
{
    BomVersion      locBomVersion;
    RouteVersion    locRouteVersion;
    ;
    if (actualBomId)
    {
        select firstonly locBomVersion
        where locBomVersion.ItemId==callerProdTable.ItemId
           && locBomVersion.BOMId==callerProdTable.BomId;

        if (locBomVersion)
        {
            BomVersion_ds.positionToRecord(locBomVersion);
        }
    }

    if (actualRouteId)
    {
        select firstonly locRouteVersion
        where locRouteVersion.ItemId==callerProdTable.ItemId
           && locRouteVersion.RouteId==callerProdTable.RouteId;

        if (locRouteVersion)
        {
            RouteVersion_ds.positionToRecord(locRouteVersion);
        }
    }
}

void replaceBySelection()
{
    ProdTable prodTable;                                                       
    FormDataSource formDataSource;

    if (callerProdTable.ProdStatus!=ProdStatus::Created)
    {
        return;
    }

    if (AVAChangeBOMRoute::runBOMRouteReplacement(callerProdTable, bomVersion, routeVersion))
    {
        element.close();

        if(element.args().dataset() == tablenum(ProdTable))
        {
            prodTable = element.args().record();
            formDataSource = FormDataUtil::getFormDataSource(prodTable);
            formDataSource.research(true);
        }
    }
}

/// <summary>
/// Returns currenty active BOMVersion record
/// </summary>
/// <returns>BOMVersion</returns>
public BOMVersion findActiveBomVersion()
{
    BOMVersion avaBOMVersion;

    select firstonly avaBOMVersion
        where avaBOMVersion.ItemId == callerProdTable.ItemId
        && avaBOMVersion.Approved == NoYes::Yes
        && avaBOMVersion.FromDate >= dateNull()
        && avaBOMVersion.FromDate <= DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone())    
        && (avaBOMVersion.ToDate == dateNull()
            || (avaBOMVersion.ToDate >= DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone())
            && avaBOMVersion.ToDate <= dateMax()))
        && avaBOMVersion.Active == NoYes::Yes;

    return avaBOMVersion;
}

/// <summary>
/// Returns currenty active RouteVersion record
/// </summary>
/// <returns>RouteVersion</returns>
public RouteVersion findActiveRouteVersion()
{
    RouteVersion avaRouteVersion;

    select firstonly avaRouteVersion
        where avaRouteVersion.ItemId == callerProdTable.ItemId
        && avaRouteVersion.Approved == NoYes::Yes
        && avaRouteVersion.FromDate >= dateNull()
        && avaRouteVersion.FromDate <= DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone())
        && (avaRouteVersion.ToDate == dateNull()
            || (avaRouteVersion.ToDate >= DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone())
            && avaRouteVersion.ToDate <= dateMax()))
        && avaRouteVersion.Active == NoYes::Yes;

    return avaRouteVersion;
}

/// <summary>
/// init method
/// </summary>
public void init()
{
    QueryBuildDatasource qbds;

    super();

    qbds                = this.query().dataSourceTable(tablenum(BOMVersion));
    rangeBomItem        = qbds.addRange(fieldnum(BOMVersion, Itemid));
    rangeBomApproved    = qbds.addRange(fieldnum(BOMVersion, Approved));
    rangeBomDateFrom    = qbds.addRange(fieldNum(BOMVersion, FromDate));
    rangeBomDateTo      = qbds.addRange(fieldNum(BOMVersion, ToDate));

    rangeBomItem.status(RangeStatus::Locked);
    rangeBomApproved.status(RangeStatus::Locked);
    rangeBomDateFrom.status(RangeStatus::Locked);
    rangeBomDateTo.status(RangeStatus::Locked);
}

/// <summary>
/// executeQuery method
/// </summary>
public void executeQuery()
{
    rangeBomItem.value(queryvalue(callerProdTable.ItemId));
    rangeBomApproved.value(queryvalue(NoYes::Yes));
    rangeBomDateFrom.value(queryRange(dateNull(), DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone())));
    rangeBomDateTo.value(queryRange(DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()), dateMax()));
    rangeBomDateTo.value(queryValue(dateNull()));

    super();

    BOMVersion_ds.positionToRecord(element.findActiveBOMVersion());
}

/// <summary>
/// active method
/// </summary>
/// <returns>int</returns>
public int active()
{
    int ret;

    ret = super();

    element.replaceButtonEnabled();

    return ret;
}

public void modified()
{
    super();

    //'Configuration' and 'Configuration Group' are mutually exclusive
    //if Config was set, Config Group must be erased
    if (inventDimBom.ConfigId)
    {
        bom.ConfigGroupId       = '';
    }
    BOM.modifiedInventDim(InventDimBOM, fieldNum(InventDim, configId));
}

public void modified()
{
    super();
    BOM.modifiedInventDim(InventDimBOM, fieldNum(InventDim, InventColorId));
}

public void modified()
{
    super();
    BOM.modifiedInventDim(InventDimBOM, fieldNum(InventDim, InventSizeId));
}

public void modified()
{
    super();
    BOM.modifiedInventDim(InventDimBOM, fieldNum(InventDim, InventStyleId));
}

public void modified()
{
    super();
    BOM.modifiedInventDim(InventDimBOM, fieldNum(InventDim, InventVersionId));
}

/// <summary>
/// init method
/// </summary>
public void init()
{
    QueryBuildDatasource qbds;

    super();

    qbds                = this.query().dataSourceTable(tablenum(RouteVersion));
    rangeRouteItem      = qbds.addRange(fieldnum(RouteVersion, Itemid));
    rangeRouteApproved  = qbds.addRange(fieldnum(RouteVersion, Approved));
    rangeRouteDateFrom  = qbds.addRange(fieldNum(RouteVersion, FromDate));
    rangeRouteDateTo    = qbds.addRange(fieldNum(RouteVersion, ToDate));

    rangeRouteItem.status(RangeStatus::Locked);
    rangeRouteApproved.status(RangeStatus::Locked);
    rangeRouteDateFrom.status(RangeStatus::Locked);
    rangeRouteDateTo.status(RangeStatus::Locked);
}

/// <summary>
/// executeQuery method
/// </summary>
public void executeQuery()
{
    rangeRouteItem.value(queryvalue(callerProdTable.ItemId));
    rangeRouteApproved.value(queryvalue(NoYes::Yes));
    rangeRouteDateFrom.value(queryRange(dateNull(), DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone())));
    rangeRouteDateTo.value(queryRange(DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()), dateMax()));
    rangeRouteDateTo.value(queryValue(dateNull()));

    super();

    RouteVersion_ds.positionToRecord(element.findActiveRouteVersion());
}

/// <summary>
/// active method
/// </summary>
/// <returns>int</returns>
public int active()
{
    int ret;

    ret = super();

    element.replaceButtonEnabled();

    return ret;
}

/// <summary>
/// clicked button for button ReplaceButton
/// </summary>
public void clicked()
{
    super();
    element.replaceBySelection();
}

boolean leave()
{
    boolean         ret;
    ConfigGroup     configGrp;
    Dialog          dialog;
    DialogField     dialogName;
    ConfigGroupId   configGroupId = this.text();

    if (configGroupId && ! ConfigGroup::find(configGroupId))
    {
        dialog      = new Dialog("@SYS25307");
        dialogName  = dialog.addField(extendedTypeStr(Name),"@SYS6303");
        if (! dialog.run())
        {
            return false;
        }

        ttsbegin;
        configGrp.ConfigGroupId     = configGroupId;
        configGrp.Name              = dialogName.value();
        configGrp.insert();
        ttscommit;
    }

    ret = super();

    return ret;
}
